/** Script nonces are generated by the server per response, never from headers. */
export function contentSecurityPolicy(nonce: string, development = false) {
  if (!/^[A-Za-z0-9+/]{32,64}={0,2}$/.test(nonce))
    throw new Error("INVALID_NONCE");
  return [
    "default-src 'self'",
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${development ? " 'unsafe-eval'" : ""}`,
    "script-src-attr 'none'",
    // React Aria uses inline positioning/style properties. Allow styles, not
    // executable inline scripts; all image/font/network destinations stay local.
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data:",
    "font-src 'self'",
    `connect-src 'self'${development ? " ws:" : ""}`,
    "object-src 'none'",
    "frame-src 'none'",
    "frame-ancestors 'none'",
    "base-uri 'none'",
    "form-action 'self'",
  ].join("; ");
}
